// RUNNABLE: demonstrates Suspense's underlying 'throw a promise' contract.
function createResource(ms, value) {
  let status = 'pending';
  let result;
  const promise = new Promise(resolve => setTimeout(() => resolve(value), ms))
    .then(v => { status = 'success'; result = v; });
  return {
    read() {
      if (status === 'pending') throw promise; // suspends the nearest boundary
      return result;
    }
  };
}

const resource = createResource(1500, 'Loaded data!');

function SlowData() {
  const data = resource.read();
  return <h2>{data}</h2>;
}

function App() {
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <p>Wait ~1.5s for the data to resolve:</p>
      <React.Suspense fallback={<h2>Loading…</h2>}>
        <SlowData />
      </React.Suspense>
    </div>
  );
}

