function wrapPromise(promise) {
  let status = 'pending';
  let result;
  const suspender = promise.then(
    v => { status = 'success'; result = v; },
    e => { status = 'error'; result = e; }
  );
  return {
    read() {
      if (status === 'pending') throw suspender; // suspend
      if (status === 'error') throw result;       // let an Error Boundary catch it
      return result;
    }
  };
}

const resource = wrapPromise(
  new Promise(r => setTimeout(() => r('Done!'), 1000))
);

function Content() {
  return <h2>{resource.read()}</h2>;
}

function App() {
  return (
    <React.Suspense fallback={<h3>Loading…</h3>}>
      <Content />
    </React.Suspense>
  );
}
